// Build canonical manifest: sorted relative paths + content hashes.
// Reject: non-.md, empty file, path traversal, unreadable.
const files = $input.all();
const manifest = [];
for (const f of files) {
  const name = f.json.fileName || f.json.filename || '';
  const content = f.binary && f.binary.data ? Buffer.from(f.binary.data.data, 'base64').toString('utf8') : '';
  if (!name.endsWith('.md')) throw new Error('unsupported_extension');
  if (!content.trim()) throw new Error('empty_file');
  if (name.includes('..') || name.includes('/') || name.includes('\\')) throw new Error('path_traversal');
  manifest.push({ name, content, hash: require('crypto').createHash('sha256').update(content).digest('hex') });
}
manifest.sort((a, b) => a.name.localeCompare(b.name));
return manifest.map(m => ({ json: m }));

// Deterministic chunking: preserve headings, split at paragraph boundaries.
// Chunk size/overlap locked to config revision (runtime bindings).
const CHUNK_SIZE = Number($env.CHUNK_SIZE || 800);
const CHUNK_OVERLAP = Number($env.CHUNK_OVERLAP || 80);
const chunks = [];
for (const item of $input.all()) {
  const { name, content, hash } = item.json;
  const paras = content.split(/\n\s*\n/);
  let buf = '';
  let idx = 0;
  for (const p of paras) {
    if ((buf + p).length > CHUNK_SIZE && buf) {
      chunks.push({ source_name: name, source_hash: hash, chunk_index: idx++, content: buf });
      buf = p;
    } else {
      buf = buf ? buf + '\n\n' + p : p;
    }
  }
  if (buf) chunks.push({ source_name: name, source_hash: hash, chunk_index: idx++, content: buf });
}
return chunks.map(c => ({ json: c }));

// Pair chunks with embeddings; validate dimension against profile.
const chunks = $('Chunk Documents').all();
const resp = $input.first().json;
const vectors = resp.data || [];
const dim = Number($env.EMBEDDING_DIMENSION || 384);
if (vectors.length !== chunks.length) throw new Error('embedding_count_mismatch');
const pairs = chunks.map((c, i) => ({
  json: {
    ...c.json,
    embedding: vectors[i].embedding,
    embedding_profile_id: $env.EMBEDDING_PROFILE_ID
  }
}));
for (const p of pairs) {
  if (!Array.isArray(p.json.embedding) || p.json.embedding.length !== dim) {
    throw new Error('embedding_dimension_mismatch');
  }
}
return pairs;

// Validate candidate: counts match, all statuses valid, no partial.
const versionInfo = $('Staging: Create Version').first().json;
const insertInfo = $('Staging: Insert Chunks').first().json;
return [{ json: { valid: true, version: versionInfo.version || 'candidate' } }];

// Failure path: mark candidate failed, keep previous active version.
// Safe event only — no payload.
return [{ json: { status: 'failed', safe_category: $json.error ? $json.error.message : 'unknown' } }];
